import React, { useState, useRef } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { db } from "../../firebaseConfig";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import emailjs from "emailjs-com";

const ContactForm = () => {
  const { t } = useTranslation();

  interface FormData {
    name: string;
    email: string;
    phone: string;
    city: string;
    renovationType: string[];
    budget: string;
    status: string;
    contactMethod: string;
    otherDetails: string;
  }

  const initialFormData: FormData = {
    name: "",
    email: "",
    phone: "",
    city: "",
    renovationType: [],
    budget: "",
    status: "",
    contactMethod: "",
    otherDetails: "",
  };

  const [formData, setFormData] = useState<FormData>(initialFormData);
  const [errors, setErrors] = useState<Partial<Record<keyof FormData, string>>>(
    {}
  );
  const [formErrorMessage, setFormErrorMessage] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formSubmitted, setFormSubmitted] = useState(false);

  const nameRef = useRef<HTMLInputElement>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const phoneRef = useRef<HTMLInputElement>(null);
  const cityRef = useRef<HTMLInputElement>(null);

  const renovationOptions = [
    "full_home",
    "bathroom",
    "kitchen",
    "outdoor",
    "commercial",
    "other",
  ];

  const budgetOptions = [
    "less_than_10k",
    "between_10k_30k",
    "more_than_30k",
    "discuss_in_consultation",
  ];

  const statusOptions = [
    "exploring",
    "ready_within_3_months",
    "have_blueprints",
  ];

  const contactMethods = ["phone", "whatsapp", "email"];

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    if (type === "checkbox" && name === "renovationType") {
      setFormData((prev) => {
        const updated = checked
          ? [...prev.renovationType, value]
          : prev.renovationType.filter((item) => item !== value);
        return { ...prev, renovationType: updated };
      });
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }));
    }
  };

  const validateForm = (): boolean => {
    const newErrors: Partial<Record<keyof FormData, string>> = {};
    let firstErrorField: HTMLElement | null = null;

    if (
      !formData.name ||
      formData.name.trim().length < 4 ||
      /\d/.test(formData.name)
    ) {
      newErrors.name = t("form.errors.name") ?? "";
      firstErrorField = nameRef.current;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      newErrors.email = t("form.errors.email") ?? "";
      if (!firstErrorField) firstErrorField = emailRef.current;
    }

    const digitsOnly = formData.phone.replace(/\D/g, "");
    if (digitsOnly.length !== 10) {
      newErrors.phone = t("form.errors.phone") ?? "";
      if (!firstErrorField) firstErrorField = phoneRef.current;
    }

    if (
      !formData.city ||
      formData.city.trim().length < 4 ||
      /\d/.test(formData.city)
    ) {
      newErrors.city = t("form.errors.city") ?? "";
      if (!firstErrorField) firstErrorField = cityRef.current;
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length > 0) {
      setFormErrorMessage(t("form.errors.general") ?? "");
      firstErrorField?.scrollIntoView({ behavior: "smooth", block: "center" });
      firstErrorField?.focus();
      return false;
    }

    setFormErrorMessage("");
    return true;
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);

    try {
      await addDoc(collection(db, "submissions"), {
        ...formData,
        timestamp: Timestamp.now(),
      });

      await emailjs.send(
        "service_1rvusuk",
        "template_tp4dj4h",
        {
          name: formData.name,
          email: formData.email,
          phone: formData.phone,
          city: formData.city,
          renovationType: formData.renovationType.join(", "),
          budget: formData.budget,
          status: formData.status,
          contactMethod: formData.contactMethod,
          otherDetails: formData.otherDetails,
        },
        "u2Op-9wm_t5yR4it5"
      );
      setFormData(initialFormData);
      setErrors({});
      setFormSubmitted(true);
      setFormErrorMessage("");
    } catch (error) {
      console.error("Error submitting form:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleResetForm = () => {
    setFormSubmitted(false);
    setFormData(initialFormData);
    setFormErrorMessage("");

    setTimeout(() => {
        formRef.current?.scrollIntoView({ behavior: "smooth" });
    }, 100); 
  };

  const hasValidationErrors = Object.values(errors).some((val) => val);
  const formRef = useRef<HTMLFormElement | null>(null);


  return (
    <section className="max-w-3xl mx-auto p-0 sm:p-6">
      <h2 className="text-2xl font-bold mb-4">{t("form.title")}</h2>
      <p className="mb-6 text-gray-700">{t("form.description")}</p>

      {formSubmitted ? (
        <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-6 rounded text-center">
          <p className="text-lg font-semibold mb-4">{t("form.success")}</p>
          <button
            onClick={handleResetForm}
            className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
          >
            {t("form.backToForm")}
          </button>
        </div>
      ) : (
        <form ref={formRef} onSubmit={handleSubmit} className="space-y-6">
          {formErrorMessage && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
              <p>{formErrorMessage}</p>
            </div>
          )}

          <fieldset className="flex flex-col border gap-4 rounded px-4 pb-4">
            <legend className="font-semibold text-lg mb-2">
              {t("form.clientInfo")}
            </legend>

            <input
              ref={nameRef}
              className={styles.input}
              name="name"
              value={formData.name}
              onChange={(e) => {
                const value = e.target.value;
                if (/^[A-Za-zÀ-ÿ\s'-]*$/.test(value) || value === "") {
                  setFormData({ ...formData, name: value });
                }
              }}
              onBlur={validateForm}
              placeholder={t("form.name") || ""}
            />
            {errors.name && (
              <p className="text-red-600 text-sm">{errors.name}</p>
            )}

            <input
              ref={emailRef}
              className={styles.input}
              name="email"
              type="email"
              value={formData.email}
              onChange={(e) =>
                setFormData({ ...formData, email: e.target.value })
              }
              onBlur={validateForm}
              placeholder={t("form.email") || ""}
            />
            {errors.email && (
              <p className="text-red-600 text-sm">{errors.email}</p>
            )}

            <input
              ref={phoneRef}
              className={styles.input}
              name="phone"
              value={formData.phone}
              onChange={(e) => {
                const digits = e.target.value.replace(/\D/g, "").slice(0, 10);
                const formatted = digits.replace(
                  /(\d{0,3})(\d{0,3})(\d{0,4})/,
                  (_, p1, p2, p3) =>
                    `${p1 ? `(${p1}` : ""}${p2 ? `) ${p2}` : ""}${
                      p3 ? ` ${p3}` : ""
                    }`
                );
                setFormData({ ...formData, phone: formatted });
              }}
              onBlur={validateForm}
              placeholder={t("form.phone") || ""}
            />
            {errors.phone && (
              <p className="text-red-600 text-sm">{errors.phone}</p>
            )}

            <input
              ref={cityRef}
              className={styles.input}
              name="city"
              value={formData.city}
              onChange={(e) => {
                const value = e.target.value;
                if (/^[A-Za-zÀ-ÿ\s'-]*$/.test(value) || value === "") {
                  setFormData({ ...formData, city: value });
                }
              }}
              onBlur={validateForm}
              placeholder={t("form.city") || ""}
            />
            {errors.city && (
              <p className="text-red-600 text-sm">{errors.city}</p>
            )}
          </fieldset>

          <fieldset className="border rounded p-4 grid grid-cols-1 sm:grid-cols-2 gap-4">
            <legend className="font-semibold text-lg mb-2">
              {t("form.projectDetails")}
            </legend>

            <article className="p-2">
              <p className="font-medium">{t("form.renovationQuestion")}</p>
              {renovationOptions.map((key) => (
                <label key={key} className="block">
                  <input
                    type="checkbox"
                    name="renovationType"
                    value={key}
                    checked={formData.renovationType.includes(key)}
                    onChange={handleChange}
                  />{" "}
                  {t(`form.renovation.${key}`)}
                </label>
              ))}
              {formData.renovationType.includes("other") && (
                <textarea
                  name="otherDetails"
                  value={formData.otherDetails}
                  onChange={handleChange}
                  placeholder={t("form.otherPlaceholder") || ""}
                  className={styles.input}
                />
              )}
            </article>

            <article className="p-2">
              <p className="font-medium">{t("form.budgetQuestion")}</p>
              {budgetOptions.map((key) => (
                <label key={key} className="block">
                  <input
                    type="radio"
                    name="budget"
                    value={key}
                    checked={formData.budget === key}
                    onChange={handleChange}
                  />{" "}
                  {t(`form.budget.${key}`)}
                </label>
              ))}
            </article>

            <article className="p-2">
              <p className="font-medium">{t("form.statusQuestion")}</p>
              {statusOptions.map((key) => (
                <label key={key} className="block">
                  <input
                    type="radio"
                    name="status"
                    value={key}
                    checked={formData.status === key}
                    onChange={handleChange}
                  />{" "}
                  {t(`form.status.${key}`)}
                </label>
              ))}
            </article>
          </fieldset>

          <fieldset className="border p-4 rounded">
            <legend className="font-semibold text-lg mb-2">
              {t("form.contact")}
            </legend>
            {contactMethods.map((method) => (
              <label key={method} className="block">
                <input
                  type="radio"
                  name="contactMethod"
                  value={method}
                  checked={formData.contactMethod === method}
                  onChange={handleChange}
                />{" "}
                {t(`form.contactMethod.${method}`)}
              </label>
            ))}
          </fieldset>

          <button
            type="submit"
            disabled={isSubmitting || hasValidationErrors}
            className={`mt-4 bg-accent text-white px-6 py-2 rounded w-full ${
              isSubmitting || hasValidationErrors
                ? "opacity-50 cursor-not-allowed"
                : "hover:bg-accent-dark"
            }`}
          >
            {isSubmitting ? t("form.sending") : t("form.submit")}
          </button>
        </form>
      )}
      <p className="mt-8 text-center text-gray-600">{t("form.thankYou")}</p>
    </section>
  );
};

export default ContactForm;

const styles = {
  input: "w-full p-2 border rounded",
};
